import {weatherConcealed,countPending,narrativeWeather} from './weather-presentation.js';
import {companyOperationsHTML} from './company-operations.js';
import {createNarrative,commitNarrative} from './narrative.js';
import {undoFrame,redoFrame} from './transactions.js';
import {latestSceneHTML,rulerSummaryHTML,rosterHTML,rosterCardsHTML,profileHTML} from './narrative-ui.js';
import {workspaceKeys} from './workspace-mode.js';
import {createDebugTools} from './debug-tools.js';
import {debugState,validateDebugState} from './debug-state.js';
import {SCENARIOS,scenarioFor,finalTurn,scenarioCaption,setupInstructions} from './scenarios.js';
import {chinaTrade} from './china-trade.js';
import {confirmInApp} from './confirm-dialog.js';
import {chroniclePanelHTML,chroniclePage,readableChronicle} from './chronicle.js';
import {loadActionProgress,saveActionProgress,restoreActionProgress} from './action-progress.js';
import {operationsBlockReason,governorTaxCount,generalTaxUsed,taxBlockReason} from './administration.js';
import {END_REASONS,canEndGame,endingInstructions} from './game-end.js';
import {TURN_PHASES,turnGuideHTML} from './turn-guide.js';
import {createEventStack,drawRequest,pendingEvent,exposedRegion,TILES} from './event-stack.js';
import {phaseFor,phaseActive,parliamentFinished,STORM_FACES} from './india-phase.js';
import {openIndiaPhase} from './phase-dialog.js';
import {openGameActions,ACTION_DRAFT} from './action-dialogs.js';
import {resolveAction,orderLabel} from './actions.js';
import {enhanceChoices} from './choice-controls.js';
import {TRADE_ROUTES,elephantPlacement} from './map-geometry.js';
import {mapAffiliation,regionMarker} from './map-markers.js';
import {enhanceNumbers} from './number-controls.js';
let cleanupNumbers=()=>{},cleanupChoices=()=>{};
import {openDeployment} from './deploy.js';
import {IDS,PRESIDENCIES,REGIONS,ALLIANCES,LAW_NAMES,clone,initialState,validate,controlLabel,summary,regionsLostThisTurn,encode,decode} from './model.js';
const $=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const workspace=workspaceKeys(),DEBUG=workspace.debug,KEY=workspace.campaign,SLOTS=workspace.slots;
let debugTools=null;
let state=DEBUG?debugState():initialState(),undo=[],undoProgress=[],redo=[],startupProgress=null,logFilter={turn:'all',kind:'all',page:0},selected='delhi',tab='map',guidePhase='london',zoom=1,storageBroken=false,unloadedSave=null,toastTimer;
function notify(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function storageError(t){storageBroken=true;$('save-status').textContent='Not saved';$('storage-alert').hidden=false;$('storage-alert').textContent=t+' Export a backup from Saved games before closing this page.';}
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=decode(raw);if(!DEBUG&&parsed.state.debugMode)throw Error('Debug saves belong in Debug mode.');if(DEBUG)validateDebugState(parsed.state);state=parsed.state;undo=parsed.undo;undoProgress=parsed.undoProgress;redo=parsed.redo;startupProgress=parsed.progress;}}catch(e){unloadedSave=localStorage.getItem(KEY);storageError(e.message+' The saved campaign could not be loaded. The stored copy has been left untouched. Start a new campaign or import a current-version save.');}
function persist(){if(storageBroken)return;try{localStorage.setItem(KEY,campaignPayload());$('save-status').textContent='Saved in this browser';}catch(e){storageError('Browser storage is unavailable or full.');}}
function campaignPayload(){return encode(state,undo,loadActionProgress(state),undoProgress,redo);}
function applyResult(result,carryProgress=null){if(!result.presentationOnly)result.state=commitNarrative(state,result);validate(result.state);if(DEBUG)validateDebugState(result.state);undo.push(clone(state));undoProgress.push(loadActionProgress(state));undo=undo.slice(-20);undoProgress=undoProgress.slice(-20);redo=[];state=result.state;if(carryProgress)restoreActionProgress(state,carryProgress);persist();render();notify('Action recorded.');}
function deployFromArmy(army=null){if(storageBroken){notify('Start a new campaign or import a current-version save before recording actions.');return;}if(hasPending()){actions();return;}openDeployment({state,showDialog,esc,apply:applyResult,army});}
function actions(start){if(narrativeWeather(state)&&loadActionProgress(state)?.input.type==='phase-start'){indiaPhase();return;}if(storageBroken){notify('Start a new campaign or import a current-version save before recording actions.');return;}openGameActions({state,showDialog,apply:applyResult,esc,start,onPhase:()=>indiaPhase(),onProgressSaved:persist});}
function hasPending(){return !storageBroken&&!!loadActionProgress(state);}
function indiaPhase(){const pending=loadActionProgress(state);if(narrativeWeather(state)&&pending?.input.type==='phase-start'&&!phaseFor(state))applyResult(resolveAction(state,pending.input));if(storageBroken){notify('Start a new campaign or import a current-version save before recording actions.');return;}if(state.gameEnd){actions();return;}if(hasPending()){actions();return;}if(state.eventStack?.pending){drawNextEvent();return;}openIndiaPhase({state,showDialog,apply:applyResult,esc,drawEvent:drawNextEvent,blackmail:()=>actions('blackmail-menu'),onPresentation:next=>{state=validate(next);persist();render();}});}
function drawNextEvent(overrides={}){if(weatherConcealed(state)||countPending(state)){indiaPhase();return;}if(hasPending()){actions();return;}const p=phaseFor(state);if(!p||p.status!=='events'||p.completed>=p.total){indiaPhase();return;}if(!state.eventStack.pending)applyResult(resolveAction(state,drawRequest(state.eventStack)));actions({...pendingEvent(state.eventStack),...(Number.isInteger(overrides.stormFace)?{stormFace:overrides.stormFace,storm:overrides.storm}:{}),...(overrides.rolls?{rolls:overrides.rolls}:{})});}
function option(v,label,current){return `<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label)}</option>`;}
function showDialog(title,body,actions=''){ cleanupNumbers();cleanupChoices();$('dialog-content').onchange=null; $('dialog-content').innerHTML=`<div class="dialog-head"><h3>${esc(title)}</h3><button id="close-dialog" aria-label="Close dialog">×</button></div>${body}<p id="form-error" class="error" role="alert"></p>${actions?`<div class="dialog-actions">${actions}</div>`:''}`; cleanupNumbers=enhanceNumbers($('dialog-content'));cleanupChoices=enhanceChoices($('dialog-content'));$('close-dialog').onclick=()=>{$('dialog-content').onchange=null;$('dialog').close();};$('dialog').oncancel=()=>{$('dialog-content').onchange=null;};if(!$('dialog').open)$('dialog').showModal();}
function formError(e){$('form-error').textContent=e.message||e;}
function setTab(value){tab=value;render();}
function render(){
 $('campaign-title').textContent=tab==='map'?state.campaignName:({register:'Campaign record',alliances:'Local alliances',design:'The first milestone',guide:'Turn guide'})[tab];
 $('section-label').textContent=({map:'THE SITUATION IN INDIA',register:'A RECORD OF THE BOARD',alliances:'THE COMPANY’S PARTNERS',design:'BUILD NOTES & DESIGN',guide:'QUICK RULES REFERENCE'})[tab];
 $('page-subtitle').textContent=`${scenarioCaption(state)}${state.gameEnd?' · Game ended':phaseActive(state)?' · Events in India':phaseFor(state)?(parliamentFinished(state)?' · Upkeep and Refresh':' · Parliament'):''}`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));
 ['map','register','alliances','design','guide'].forEach(t=>$(t+'-page').hidden=t!==tab);
 $('undo').disabled=!undo.length;$('redo').disabled=!redo.length;
 if(DEBUG)$('page-subtitle').textContent='DEBUG · '+$('page-subtitle').textContent;
 renderMap();renderOperations();renderRegion();renderNarrative();renderContext();renderRegister();renderAlliances();renderDesign();renderPhase();renderStack();renderGuide();renderGovernorGeneral();debugTools?.render(selected);
}
function renderNarrative(){
 $('narrative-panel').innerHTML=latestSceneHTML(state);
 if(!state.narrative)return;
 $('open-roster').onclick=()=>setTab('register');
 document.querySelectorAll('[data-narrative-mode]').forEach(b=>b.onclick=()=>{const next=clone(state),progress=loadActionProgress(state);next.narrative.intensity=b.dataset.narrativeMode;applyResult({state:next,presentationOnly:true},progress);});
}
function characterProfile(id){const c=state.narrative?.characters[id];if(c)showDialog(c.name,profileHTML(state,id));}
function bindRoster(){
 if(!state.narrative)return;const filter={query:'',region:'all',role:'all'};
 const bind=()=>document.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>characterProfile(b.dataset.character));
 const update=()=>{$('character-list').innerHTML=rosterCardsHTML(state,filter);bind();};
 $('character-search').oninput=()=>{filter.query=$('character-search').value;update();};
 for(const key of ['region','role'])document.querySelectorAll('[data-character-'+key+']').forEach(b=>b.onclick=()=>{filter[key]=b.dataset[key==='region'?'characterRegion':'characterRole'];document.querySelectorAll('[data-character-'+key+']').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));update();});bind();
}
function renderGuide(){
 $('guide-page').innerHTML=turnGuideHTML(guidePhase,state.turn,state);
 $('phase-shortcuts').hidden=tab!=='guide';
 $('phase-shortcuts').innerHTML=TURN_PHASES.map(p=>`<button data-guide-phase="${p.id}" class="phase-shortcut ${guidePhase===p.id?'active':''}" aria-pressed="${guidePhase===p.id}"><span>${p.roman}</span>${p.short}</button>`).join('');
 document.querySelectorAll('[data-guide-phase]').forEach(button=>button.onclick=()=>{guidePhase=button.dataset.guidePhase;setTab('guide');});
}
function hydrateStack(s=state,frames=undo){const baseline=s.eventStack||createEventStack();s.eventStack=baseline;for(const previous of frames)if(!previous.eventStack)previous.eventStack=clone(baseline);}
function renderStack(){
 const stack=state.eventStack,region=exposedRegion(stack),pending=stack.pending?TILES[stack.pending.tileId]:null;
 $('event-stack-panel').innerHTML=`<div class="stack-region" style="border-color:${region?REGIONS[region].color:'#b18545'}"><p class="eyebrow">EXPOSED EVENT STACK REGION</p><strong>${region?esc(REGIONS[region].name):'Empty · Shuffle pending'}</strong></div><div class="stack-details"><p>${stack.draw.length} tiles in draw stack · ${stack.discard.length} discarded</p><p>${pending?`Revealed event awaiting resolution: <b>${esc(({crisis:'Crisis',leader:'Leader',turmoil:'Turmoil',windfall:'Windfall',peace:'Peace',shuffle:'Shuffle',foreign:'Foreign Invasion'})[pending.event])}</b>`:'The event front stays hidden until you draw. This region is visible throughout the turn.'}</p></div>`;
}
function renderPhase(){
 const p=phaseFor(state),panel=$('india-phase-panel');

 $('events-phase-action').disabled=!!state.gameEnd;
 $('end-game-action').disabled=!canEndGame(state);
 $('end-game-action').title=state.gameEnd?'This game has ended.':phaseActive(state)?'Finish all Events in India before ending the game.':'Close the campaign chronicle and proceed to Final Scoring.';
 if(state.gameEnd){panel.hidden=false;panel.innerHTML=`<div><p class="eyebrow">CHRONICLE COMPLETE · TURN ${state.gameEnd.turn}</p><strong>${esc(END_REASONS[state.gameEnd.reason])}</strong><p>${esc(endingInstructions(state,state.gameEnd.reason)[0])}</p>${state.gameEnd.note?`<p class="closing-note">${esc(state.gameEnd.note)}</p>`:''}<p>The final map and campaign record remain available. Use Saved games to export a backup, or Undo to reopen.</p></div><div class="phase-buttons"><button id="view-chronicle">View campaign record</button></div>`;$('view-chronicle').onclick=()=>setTab('register');return;}
 $('events-phase-action').textContent=weatherConcealed(state)?'Ocean conditions':!p?'Events in India':p.status==='ships'?'Resolve storms':p.status==='complete'?'Events in India ✓':p.completed===p.total?'Finish Events in India':state.eventStack?.pending?'Resume revealed event':`Events in India · ${p.completed}/${p.total}`;
 panel.hidden=!p;if(!p){panel.innerHTML='';return;}
 if(weatherConcealed(state)){
  $('events-phase-action').textContent='Ocean conditions';
  panel.innerHTML='<div><p class="eyebrow">EVENTS IN INDIA</p><strong>Ocean conditions</strong></div><div class="phase-buttons"><button id="phase-storms" class="primary">View ocean conditions</button></div>';$('phase-storms').onclick=indiaPhase;return;
 }
 const face=STORM_FACES[p.face];
 if(parliamentFinished(state)){
  panel.innerHTML=`<div><p class="eyebrow">PARLIAMENT COMPLETE</p><strong>${finalTurn(state)?'Final Scoring':'Upkeep and Refresh'}</strong><p>${finalTurn(state)?'Pay prize upkeep, skip refresh and proceed to Final Scoring.':'Finish upkeep and refresh on the table, then begin the next turn.'} The India map needs no further changes.</p></div><div class="phase-buttons">${!finalTurn(state)?'<button id="after-upkeep-next" class="primary">Begin next turn</button>':'<button id="final-scoring-info">Final Scoring reminder</button>'}</div>`;
  if($('after-upkeep-next'))$('after-upkeep-next').onclick=()=>actions('next-turn');
  if($('final-scoring-info'))$('final-scoring-info').onclick=()=>showDialog('Final Scoring',`<p>This is the final turn. Complete prize upkeep, skip the refresh steps and resolve Final Scoring on the physical board. There is no next turn.</p>`);
  return;
 }
 panel.innerHTML=`<div><p class="eyebrow">${p.status==='complete'?'PHASE COMPLETE':'EVENTS IN INDIA'}</p><strong>${p.completed} / ${p.total} events resolved</strong><p>${esc(face.label)}${p.status==='ships'?' · resolve ship rolls before events':p.status==='complete'?' · Parliament, or End game if the Company has failed':p.completed===p.total?' · ready to finish the phase':' · inspect the map, then draw when ready'}</p></div><div class="phase-buttons">${p.status==='ships'?'<button id="phase-storms" class="primary">Resolve ship storms</button>':p.status==='complete'?'<button id="phase-parliament">Parliament</button>':p.completed===p.total?'<button id="phase-finish" class="primary">Finish phase</button>':'<button id="phase-next" class="primary">'+(state.eventStack?.pending?'Resume revealed event':'Draw next event · '+(p.completed+1)+' of '+p.total)+'</button>'}${p.status!=='complete'?'<button id="phase-cards">Blackmail cards</button>':''}</div>`;
 if($('phase-storms'))$('phase-storms').onclick=indiaPhase;
 if($('phase-finish'))$('phase-finish').onclick=indiaPhase;
 if($('phase-next'))$('phase-next').onclick=drawNextEvent;
 if($('phase-cards'))$('phase-cards').onclick=()=>actions('blackmail-menu');
 if($('phase-parliament'))$('phase-parliament').onclick=()=>actions('parliament-menu');
}
function renderMap(){
 const s=summary(state),china=chinaTrade(state),lost=regionsLostThisTurn(state);$('stats').innerHTML=[[s.company+'/8','COMPANY REGIONS'],[s.closed+'/17','CLOSED ORDERS'],[s.unrest,'TOTAL UNREST'],[lost,'REGIONS LOST THIS TURN',`Next loss: −${lost+1} Standing`],...(china.active?[[s.opium+'/5','COMPANY OPIUM ICONS',`£${china.companyRevenue} on successful China trade · £${china.rate}/icon`]]:[])].map(([v,l,detail])=>`<div class="stat"><strong>${v}</strong><span>${l}</span>${detail?`<p class="stat-detail">${detail}</p>`:''}</div>`).join('');
 const svg=$('map-svg');svg.innerHTML=`<defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#8b3e27"/></marker></defs><rect width="1265" height="1218" fill="#f0ede3"/>`;
 svg.innerHTML+=[...IDS.filter(id=>id!==selected),selected].map(id=>{const r=REGIONS[id],v=state.regions[id],a=mapAffiliation(state,id);return `<path class="region-shape affiliation-${a.kind} ${id===selected?'selected':''}" data-region="${id}" d="${r.path}" style="--region-color:${r.color};--affiliation:${a.color}" role="button" tabindex="0" aria-label="${r.name}, ${esc(controlLabel(state,id))}, ${v.strength} tower levels, ${v.unrest} unrest"><title>${r.name} · ${esc(controlLabel(state,id))}</title></path>`;}).join('');
 svg.innerHTML+=`<g class="trade-routes" aria-label="Printed trade routes" pointer-events="none">${TRADE_ROUTES.map(([from,to,path])=>`<path d="${path}"/>`).join('')}</g>`;
 svg.innerHTML+=IDS.map(id=>regionMarker(state,id)).join('');
 svg.innerHTML+=IDS.map(id=>REGIONS[id].orders.map(([oid,x,y,value])=>`<g class="order-marker ${state.regions[id].orders[oid]?'':'closed'}" role="button" tabindex="0" data-order="${oid}" data-owner="${id}" aria-label="${REGIONS[id].name} £${value} order ${state.regions[id].orders[oid]?'open':'closed'}"><circle cx="${x}" cy="${y}" r="29"/><text x="${x}" y="${y+1}">${state.regions[id].orders[oid]?'£'+value:'×'}</text></g>`).join('')).join('');
 const e=elephantPlacement(state.elephant.from,state.elephant.to),{x,y}=e;
 if(!e.inside){const {dx,dy}=e;svg.innerHTML+=`<g class="elephant-marker" pointer-events="none" aria-label="Elephant on ${REGIONS[state.elephant.from].name} border facing ${REGIONS[state.elephant.to].name}"><title>${REGIONS[state.elephant.from].name} → ${REGIONS[state.elephant.to].name}</title><path d="M${x-dx*34} ${y-dy*34}L${x+dx*34} ${y+dy*34}" stroke="#fff5dc" stroke-width="18" stroke-linecap="round"/><path d="M${x-dx*34} ${y-dy*34}L${x+dx*34} ${y+dy*34}" stroke="#8b3e27" stroke-width="8" marker-end="url(#arrow)"/><text x="${x+20}" y="${y+32}" fill="#813c26" stroke="#fff5dc" stroke-width="3" paint-order="stroke fill" font-size="17" font-family="Arial" font-weight="bold">ELEPHANT</text></g>`;}else svg.innerHTML+=`<g pointer-events="none"><circle cx="${x}" cy="${y}" r="25" fill="#8b3e27" stroke="#fff4df" stroke-width="4"/><text x="${x}" y="${y+6}" text-anchor="middle" fill="white" font-size="18">E</text></g>`;
 const activate=(e)=>{if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(e.type==='keydown')e.preventDefault();const node=e.target.closest('[data-order],[data-region]');if(!node)return;selected=node.dataset.owner||node.dataset.region;render();if(node.dataset.order)notify(`${orderLabel(node.dataset.order)} · ${state.regions[selected].orders[node.dataset.order]?'open':'closed'}`);};
 svg.onclick=activate;svg.onkeydown=activate;
}
function orderName(id,index){const count=REGIONS[id].orders.length;return count===1?'Only order':count===2?(index===0?'Northern order':'Southern order'):(['Northern order','Middle order','Southern / eastern order'][index]);}
function renderRegion(){const r=REGIONS[selected],v=state.regions[selected],capital=v.overlord||selected,empire=IDS.filter(k=>k===capital||state.regions[k].overlord===capital);
 $('region-panel').innerHTML=`<div class="region-top" style="border-color:${r.color}"><p class="eyebrow">REGION DOSSIER</p><h3>${r.name}</h3><span class="tag">${esc(controlLabel(state,selected))}</span></div><div class="panel-body"><div class="fact-row"><span>Tower levels</span><b>${v.strength}</b></div><div class="fact-row"><span>Unrest</span><b>${v.unrest}</b></div><div class="fact-row"><span>Opium icons</span><b>${r.opium}</b></div><div class="fact-row"><span>Loot bonus</span><b>${v.lootAvailable?'£'+r.lootBonus+' available':'Claimed'}</b></div>${empire.length>1&&v.control==='indian'?`<div class="fact-row"><span>Empire strength</span><b>${empire.reduce((a,k)=>a+state.regions[k].strength,0)}</b></div>`:''}<h4 class="panel-heading">Orders</h4><div class="order-list">${r.orders.map(([oid])=>`<div class="order-button"><span>${esc(orderLabel(oid).replace(r.name+' ',''))}</span><span class="${v.orders[oid]?'':'closed-text'}">${v.orders[oid]?'○ Open':'● Closed'}</span></div>`).join('')}</div><p class="small-note">Game actions update orders and region status automatically.</p><h4 class="panel-heading">Neighbours</h4><p class="small-note">${r.neighbors.map(k=>REGIONS[k].name).join(' · ')}</p>${DEBUG?'<button id="debug-region-edit" class="wide">Edit region setup</button>':''}${rulerSummaryHTML(state,selected)}${regionActionsHTML()}</div>`;
 if($('ruler-profile'))$('ruler-profile').onclick=()=>characterProfile(state.narrative.seats[selected]);
 if($('debug-region-edit'))$('debug-region-edit').onclick=()=>debugTools?.editRegion();
 if($('region-tax-action'))$('region-tax-action').onclick=()=>actions({type:'tax',regionContext:selected});
 if($('region-governor-action'))$('region-governor-action').onclick=()=>actions({type:'governor',regionContext:selected});
}
function renderOperations(){
 $('company-operations').innerHTML=companyOperationsHTML(state,esc);
 for(const army of PRESIDENCIES)$('operations-deploy-'+army).onclick=()=>deployFromArmy(army);
 $('operations-envoy').onclick=()=>actions('envoy');
}
function regionActionsHTML(){
 const v=state.regions[selected],blocked=operationsBlockReason(state),taxReason=taxBlockReason(state,selected);
 if(v.control!=='company')return '';
 const button=(id,label,enabled)=>`<button id="${id}" class="wide" ${enabled?'':'disabled'}>${label}</button>`;
 const note=t=>t?`<p class="small-note">${esc(t)}</p>`:'';
 return `<div class="region-actions"><h4 class="panel-heading">Region administration</h4>${state.laws.governorGeneral?`${button('region-tax-action','Governor General Tax',!taxReason)}${note(taxReason||'Adds 1 unrest; this region can receive Governor General Tax unrest once per turn.')}`:`${button('region-governor-action','Governor actions',!blocked)}${note(blocked||`${governorTaxCount(state,selected)} Taxes recorded this turn. Next Tax adds ${governorTaxCount(state,selected)?1:0} unrest.`)}`}</div>`;
}
function renderGovernorGeneral(){
 const panel=$('governor-general-panel');panel.hidden=!state.laws.governorGeneral;if(panel.hidden){panel.innerHTML='';return;}
 const companies=IDS.filter(id=>state.regions[id].control==='company'),blocked=operationsBlockReason(state),done=state.history.some(h=>h.turn===state.turn&&h.actionType==='govern'&&h.input?.outcome==='success'),taxes=companies.filter(id=>!generalTaxUsed(state,id));
 panel.innerHTML=`<p class="eyebrow">COMPANY-WIDE ACTION</p><h3>Governor General</h3><p>Each six adds 1 unrest to every Company region. An unsuccessful Govern adds ${state.laws.zamindarTaxes?2:1} more unrest to every Company region.</p><p class="small-note">Affected regions: ${companies.length?companies.map(id=>esc(REGIONS[id].name)).join(', '):'none'}.</p><button id="general-govern-action" ${blocked||!companies.length||done?'disabled':''}>Report Govern check & sixes</button><p class="small-note">${esc(blocked||(done?'A successful Govern has already been recorded this turn.':!companies.length?'There are no Company regions.':'Report success, failure or catastrophe and the number of sixes together.'))}</p><button id="general-tax-action" ${blocked||!taxes.length?'disabled':''}>Governor General Tax</button><p class="small-note">${taxes.length?`${taxes.length} Company region${taxes.length===1?'':'s'} still eligible for a Tax placement. Each placement adds 1 unrest.`:'No eligible Company regions remain for Tax placement.'}</p>`;
 $('general-govern-action').onclick=()=>actions('govern');$('general-tax-action').onclick=()=>actions('tax');
}
function renderContext(){const e=state.elephant,s=summary(state);$('elephant-panel').innerHTML=`<p class="eyebrow">THE ELEPHANT</p><div class="arrow-description">${REGIONS[e.from].name}${e.to?' → '+REGIONS[e.to].name:' · Inside the region'}</div><p>${e.to?'On the border, facing '+REGIONS[e.to].name+'.':'Wholly within '+REGIONS[e.from].name+'.'} Events and conquest determine its movement.</p><button id="blackmail-shortcut" ${state.gameEnd?'disabled':''}>Blackmail cards</button>`;
 $('blackmail-shortcut').onclick=()=>actions('blackmail-menu');
 $('context-panel').innerHTML=`<p class="eyebrow">COMPANY ADMINISTRATION</p><h3>${state.laws.governorGeneral?'Governor General active':'Presidencies & Governors'}</h3><div class="context-items"><span>China office <b>${state.chinaOffice?'Opened':'Not opened'}</b></span>${state.chinaOffice?`<span>Opium in Company regions <b>${s.opium} icons</b></span><span>Potential successful China trade <b>£${chinaTrade(state).companyRevenue}</b></span><span>Rate${state.laws.envoyChina?' · Envoy to China':''} <b>£${chinaTrade(state).rate}/icon</b></span><span>Superintendent bonus <b>£${s.opium}</b></span><p class="small-note">Superintendent acts after Bengal Presidency. Trade in China is a separate physical check: one die per assigned ship, at most once per action opportunity. ${s.opium?'Resolve the check and any payments on the table; the app records no Trade in China outcome.':'No Company opium icons: Trade in China cannot be attempted.'}</p>`:'<p class="small-note">Special Envoy or Envoy to China law can create the Superintendent office. Creating it does not perform Trade in China.</p>'}<span>Zamindar Taxes <b>${state.laws.zamindarTaxes?'Active':'Not active'}</b></span><span>Sepoy Recruitment <b>${state.laws.sepoyRecruitment?'Active':'Not active'}</b></span></div><button id="admin-actions" ${state.gameEnd?'disabled':''}>${phaseFor(state)?'Events in India':'Game actions'}</button>`;
 $('admin-actions').onclick=()=>phaseFor(state)?indiaPhase():actions();
}
function renderRegister(){
 if(logFilter.turn!=='all'&&Number(logFilter.turn)>state.turn)logFilter.turn='all';
 logFilter.page=chroniclePage(state,logFilter).page;
 $('register-page').innerHTML=`<div class="record-grid"><article class="paper-card"><p class="eyebrow">BOARD REGISTER</p><h3>Eight regions, one shared record</h3><div class="table-scroll"><table class="region-table"><thead><tr><th>REGION</th><th>CONTROL</th><th>TOWER</th><th>UNREST</th><th>CLOSED</th></tr></thead><tbody>${IDS.map(id=>{const r=state.regions[id];return `<tr><td><button class="table-link" data-select="${id}">${REGIONS[id].name}</button></td><td>${esc(controlLabel(state,id))}</td><td>${r.strength}</td><td>${r.unrest}</td><td>${Object.values(r.orders).filter(x=>!x).length}/${REGIONS[id].orders.length}</td></tr>`;}).join('')}</tbody></table></div></article><article class="paper-card">${chroniclePanelHTML(state,logFilter)}</article></div>${rosterHTML(state)}`;
 bindRoster();
 document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;setTab('map');});
 document.querySelectorAll('[data-log-turn]').forEach(b=>b.onclick=()=>{logFilter.turn=b.dataset.logTurn;logFilter.page=0;renderRegister();});
 document.querySelectorAll('[data-log-kind]').forEach(b=>b.onclick=()=>{logFilter.kind=b.dataset.logKind;logFilter.page=0;renderRegister();});
 $('log-previous').onclick=()=>{logFilter.page--;renderRegister();};$('log-next').onclick=()=>{logFilter.page++;renderRegister();};$('export-chronicle').onclick=exportChronicle;
}
function renderAlliances(){$('alliances-page').innerHTML=`<div class="notice">Reference catalogue · These are independent narrative actors tied to their printed armies. Report their participation through Deploy.</div><div class="alliance-groups">${PRESIDENCIES.map(p=>`<article class="paper-card" style="border-top:4px solid ${REGIONS[p].color}"><p class="eyebrow">PRESIDENCY</p><h3>Army of ${REGIONS[p].name}</h3>${ALLIANCES.filter(a=>a.army===p).map(a=>`<div class="alliance-card"><h4>${a.name}</h4><div class="alliance-numbers">£${a.cost} COST &nbsp; · &nbsp; ${a.strength} STRENGTH</div><p>${a.voice}</p></div>`).join('')}</article>`).join('')}</div><p class="small-note">Values supplied from your physical pieces. Dialogue themes are design proposals based on historical context; each campaign supplies its own memories.</p>`;}
function renderDesign(){$('design-page').innerHTML=`<div class="design-layout"><article class="paper-card"><h3>Actions drive the map</h3><p>Deploy, India events, Special Envoy, administration, Parliament and blackmail cards update the map through their game rules. Each action previews physical instructions and can be undone.</p><p>Events draw from a saved, shuffled 20-tile digital stack. The exposed region is always visible; front effects remain hidden until drawn. Manual event resolution is retained for testing without consuming a stack tile or phase event. The app calculates order closures, Cascades, empire changes and the Elephant’s March.</p></article><article class="paper-card"><h3>At the table</h3><p>Players roll Deploy checks, officer losses and ship storm checks, resolve rerolls and blackmail cancellation, and report the final results. Company defence uses the strength you can exhaust from the physical Army.</p><p>Roll the phase storm die in the app, or roll it physically and confirm its face. The result is saved once and sets the required digital event draws. Foreign Invasion and War Against France storm dice roll automatically in the app. Each foreign-invasion strength is also saved once. No Army inventory or player identity is tracked. Region-loss reports include office removals, routs and cumulative Standing loss.</p></article><article class="paper-card"><h3>Administration and laws</h3><p>Use Company Operations for fixed-origin Army Deploy and Director of Trade Special Envoy. Use selected Company-region dossiers for Governor Tax and unsuccessful Administer. Report every successful Tax, including the first; the app adds unrest only for later Taxes in that region and turn. With Governor General active, use its separate box to report Govern results and sixes together, and each Tax placement separately. Zamindar Taxes and Sepoy Recruitment apply automatically.</p><p>Start Events in India to roll storms, resolve ships and draw one event at a time. Scandal cards remain available between events; Envoy to the Mughals must be played before the phase. Use Parliament afterward to record a law, famine relief or War Against France. Use Begin next turn to reset turn-based limits.</p></article><article class="paper-card"><h3>People and campaign records</h3><p>Scandal cards dismiss the selected player-held office without tracking its holder. New games can enable fictional rulers, families, advisers, saved scenes, dossiers, a character roster and turn chapters. Natural succession and advanced political arcs remain planned.</p><p>Campaigns autosave locally. Saved games supports snapshots and JSON backups. Unconfirmed forms are forgotten when closed. Revealed events and saved app dice resume in the same browser.</p><a class="document-link" href="design-specification.md" download>Download implementation notes ↓</a></article></div>`;}
function getSlots(){try{const s=JSON.parse(localStorage.getItem(SLOTS)||'[]');return Array.isArray(s)?s:[];}catch{return [];}}
function restore(payload){
 const decoded=decode(payload);if(!DEBUG&&decoded.state.debugMode)throw Error('Open Debug mode to import a debug save.');if(DEBUG){decoded.state.debugMode=true;validateDebugState(decoded.state);for(const frame of decoded.undo){frame.debugMode=true;validateDebugState(frame);}for(const frame of decoded.redo){frame.state.debugMode=true;validateDebugState(frame.state);if(frame.progress)frame.progress.fingerprint=JSON.stringify(frame.state);}}hydrateStack(decoded.state,decoded.undo);decoded.undoProgress=decoded.undoProgress.map((p,i)=>p?{...p,fingerprint:JSON.stringify(decoded.undo[i])}:null);restoreActionProgress(decoded.state,decoded.progress);
 unloadedSave=null;state=decoded.state;undo=decoded.undo;undoProgress=decoded.undoProgress;redo=decoded.redo;logFilter={turn:'all',kind:'all',page:0};storageBroken=false;$('storage-alert').hidden=true;persist();render();$('dialog').close();notify('Campaign restored.');
}
function downloadFile(text,type,name){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportSave(){try{if(unloadedSave){downloadFile(unloadedSave,'application/json','john-company-unchanged-unsupported-save.json');return;}downloadFile(campaignPayload(),'application/json',`john-company-${state.scenario}-turn-${state.turn}.json`);}catch(e){notify(e.message);}}
function exportChronicle(){downloadFile(readableChronicle(state,loadActionProgress(state)),'text/html',`john-company-chronicle-turn-${state.turn}.html`);}
function saveConfirmation(title,message,label,onConfirm){confirmInApp({showDialog,title,message,confirmLabel:label,onConfirm,onCancel:saves});}
function saves(){const slots=getSlots();showDialog('Saved games',`<p class="small-note">Your campaign autosaves here. JSON backups and snapshots include unfinished events, saved dice and acknowledged board instructions. Export a backup for another browser or device using this development version. Older development saves are not converted.</p><div class="fields"><label>Campaign name<input id="campaign-name" maxlength="80" value="${esc(state.campaignName)}"></label></div><button id="rename" class="wide">Save campaign name</button><h4 class="panel-heading">Named snapshots</h4>${slots.map((s,i)=>`<div class="save-slot"><div><p>${esc(s.name)}</p><small>${esc(s.date)}</small></div><div class="save-buttons"><button data-load="${i}">Load</button><button data-remove="${i}" aria-label="Remove snapshot ${esc(s.name)}">×</button></div></div>`).join('')||'<p class="small-note">No snapshots yet.</p>'}<button id="snapshot" class="wide">Save a snapshot</button><div class="dialog-actions"><button id="export">Export JSON</button><button id="menu-export-chronicle">Export readable chronicle</button><button id="import">Import JSON</button><button id="new-campaign">New game</button><button id="open-other-workspace">${DEBUG?'Return to regular game':'Open / resume debug workspace'}</button></div><input id="file" type="file" accept=".json,application/json" hidden>`);
 $('rename').disabled=!!unloadedSave;$('snapshot').disabled=!!unloadedSave;if(unloadedSave)$('export').textContent='Download unchanged stored save';
 $('rename').disabled=!!unloadedSave;$('snapshot').disabled=!!unloadedSave;
 $('rename').onclick=()=>{try{const progress=loadActionProgress(state);applyResult(resolveAction(state,{type:'rename',name:$('campaign-name').value}),progress);$('dialog').close();}catch(e){formError(e);}};
 $('snapshot').onclick=()=>{try{if(slots.length>=10)throw Error('Ten snapshots are stored. Export or remove one before adding another.');slots.unshift({name:state.campaignName+' · Turn '+state.turn,date:new Date().toLocaleString(),payload:campaignPayload()});localStorage.setItem(SLOTS,JSON.stringify(slots));saves();notify('Snapshot saved.');}catch(e){formError(e);}};
 document.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>saveConfirmation('Load snapshot?','Replace the current campaign with this snapshot? Export a JSON backup first if you want to keep the current campaign.','Load snapshot',()=>restore(slots[Number(b.dataset.load)].payload)));
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>saveConfirmation('Remove snapshot?','Remove this named snapshot? The current campaign is kept.','Remove snapshot',()=>{slots.splice(Number(b.dataset.remove),1);localStorage.setItem(SLOTS,JSON.stringify(slots));saves();}));
 $('export').onclick=exportSave;$('menu-export-chronicle').onclick=exportChronicle;$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>6000000)throw Error('Save files must be smaller than 6 MB.');const raw=await f.text();decode(raw);saveConfirmation('Import campaign?','Replace the current campaign with this imported save? Export a JSON backup first if you want to keep the current campaign.','Import campaign',()=>restore(raw));}catch(e){formError(e);}};
 $('new-campaign').onclick=()=>newCampaign();$('open-other-workspace').onclick=()=>{globalThis.location.href=DEBUG?'index.html':'debug.html';};
}
function newCampaign(scenario='1710',mode=DEBUG?'debug':'regular',narrative=false){
 const c=SCENARIOS[scenario];let started=false;
 showDialog('New game · choose a scenario',`<div class="choice-buttons" role="group" aria-label="Game mode"><button id="mode-regular" aria-pressed="${mode==='regular'}">Regular game</button><button id="mode-debug" aria-pressed="${mode==='debug'}">Debug mode</button></div>${mode==='debug'?'<p class="notice">A separate India test bench with editable setup, event deck and shared rules. Your regular game is preserved.</p>':''}<div class="scenario-choices" role="group" aria-label="Scenario">${Object.entries(SCENARIOS).map(([id,s])=>`<button data-scenario="${id}" aria-pressed="${id===scenario}" class="${id===scenario?'primary':''}"><strong>${s.label} · ${s.name}</strong><span>${s.end-s.start+1} rounds · board turns ${s.start}–${s.end}</span></button>`).join('')}</div><h4 class="panel-heading">Narrative mode</h4><p>Fictional rulers, advisers and a continuing chronicle. Select only for a new campaign.</p><div class="choice-buttons" role="group" aria-label="Narrative mode"><button id="narrative-off" aria-pressed="${!narrative}">Off</button><button id="narrative-on" aria-pressed="${narrative}">On</button></div><h4 class="panel-heading">${c.name} · setup</h4><p>${mode==='debug'?'Starts a fresh debug workspace for this scenario. The regular campaign stays saved separately.':DEBUG?'Starting a new regular game replaces the regular campaign saved in this browser. Your debug setup stays saved separately.':'Starting a new game replaces the current campaign. Export or save a snapshot first to keep it. Undo can restore the previous campaign.'}</p><ol class="action-instructions">${setupInstructions(scenario).map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p>The app sets the India map, orders, loot availability, Elephant, starting laws and offices automatically.</p>`,'<button id="new-game-back">Back</button><button id="start-scenario" class="primary">Start '+esc(c.label)+(mode==='debug'?' debug workspace':' game')+'</button>');
 document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>newCampaign(b.dataset.scenario,mode,narrative));
 $('mode-regular').onclick=()=>newCampaign(scenario,'regular',narrative);$('mode-debug').onclick=()=>newCampaign(scenario,'debug',narrative);
 $('narrative-on').onclick=()=>newCampaign(scenario,mode,true);$('narrative-off').onclick=()=>newCampaign(scenario,mode,false);
 $('new-game-back').onclick=saves;
 $('start-scenario').onclick=()=>{if(started)return;try{started=true;$('start-scenario').disabled=true;if(mode==='debug'){globalThis.location.href='debug.html?scenario='+encodeURIComponent(scenario)+'&reset=1'+(narrative?'&narrative=1':'');return;}if(DEBUG){globalThis.location.href='index.html?scenario='+encodeURIComponent(scenario)+'&reset=1'+(narrative?'&narrative=1':'');return;}redo=[];undo=[clone(state)];undoProgress=[loadActionProgress(state)];unloadedSave=null;state=initialState(scenario);hydrateStack();if(narrative)state.narrative=createNarrative(state);storageBroken=false;$('storage-alert').hidden=true;localStorage.removeItem(ACTION_DRAFT);logFilter={turn:'all',kind:'all',page:0};persist();selected=scenario==='1813'?'madras':scenario==='1758'?'bengal':'delhi';tab='map';render();$('dialog').close();notify('New '+c.label+' campaign. Undo is available.');}catch(e){started=false;$('start-scenario').disabled=false;formError(e);}};
}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
$('game-actions').onclick=()=>actions();
$('events-phase-action').onclick=indiaPhase;
$('end-game-action').onclick=()=>actions('end-game');
$('undo').onclick=()=>{if(!undo.length)return;const last=state.history.at(-1),frame=undoFrame(state,loadActionProgress(state),undo,undoProgress,redo),progress=frame.progress;({state,undo,undoProgress,redo}=frame);if(state.history.length<frame.redo.at(-1).state.history.length&&last?.kind==='action'&&(last.input?.rolls||['phase-start','stack-draw'].includes(last.input?.type)))saveActionProgress(state,last.input,'resolve');else restoreActionProgress(state,progress);persist();render();notify('Last change undone. Reverse its physical changes on the board too.');};
$('redo').onclick=()=>{const frame=redoFrame(state,loadActionProgress(state),undo,undoProgress,redo);if(!frame)return;({state,undo,undoProgress,redo}=frame);restoreActionProgress(state,frame.progress);persist();render();notify('Change restored. Repeat its physical changes on the board too.');};

$('save-menu').onclick=saves;$('zoom-in').onclick=()=>{zoom=Math.min(2.5,zoom+.25);$('map-canvas').style.width=zoom*100+'%';};$('zoom-out').onclick=()=>{zoom=Math.max(1,zoom-.25);$('map-canvas').style.width=zoom*100+'%';};$('zoom-reset').onclick=()=>{zoom=1;$('map-canvas').style.width='100%';};
$('help').onclick=()=>showDialog('Play alongside the physical board',`<p>Select a region or order to inspect it. Use the <b>Company Operations</b> Army panels for military actions, <b>Events in India</b> to start that phase, and <b>Game actions</b> for India events, Parliament and blackmail. Use the Director of Trade panel for Special Envoy and Company-region dossiers for Governor administration.</p><p>Draw each event from the digital stack; the app supplies its face and the newly exposed region, then determines the map consequences. Manual event resolution remains available under Game actions for tests. Resolve table rerolls and cancellation before reporting results. Follow each action’s physical instructions and confirm to save its changes.</p><p><b>Undo</b> restores the last app state; reverse the corresponding physical changes yourself. <b>Saved games</b> provides snapshots and JSON backups.</p>`);
const launchParams=new URLSearchParams(globalThis.location?.search||'');
if(launchParams.get('reset')==='1'&&Object.hasOwn(SCENARIOS,launchParams.get('scenario'))){
 unloadedSave=null;storageBroken=false;$('storage-alert').hidden=true;
 redo=[];undo=DEBUG?[]:[clone(state)];undoProgress=DEBUG?[]:[startupProgress];state=DEBUG?debugState(launchParams.get('scenario')):initialState(launchParams.get('scenario'));if(launchParams.get('narrative')==='1'){hydrateStack();state.narrative=createNarrative(state);}startupProgress=null;localStorage.removeItem(ACTION_DRAFT);globalThis.history?.replaceState(null,'',DEBUG?'debug.html':'index.html');
}
if(DEBUG){
 state.debugMode=true;
 debugTools=createDebugTools({getState:()=>state,getPayload:campaignPayload,apply:applyResult,restore,showDialog,esc,actions,deploy:()=>deployFromArmy(),draw:drawNextEvent,hasPending,notify,selectRegion:id=>{selected=id;render();}});
}
hydrateStack();undoProgress=undoProgress.map((p,i)=>p?{...p,fingerprint:JSON.stringify(undo[i])}:null);if(!storageBroken&&!loadActionProgress(state)&&startupProgress)try{restoreActionProgress(state,startupProgress);}catch(e){storageError(e.message);}render();if(!storageBroken)persist();
